// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title CloudInfraManager
 * @notice Manages cloud infrastructure resource allocation with graceful shutdown
 * @dev Implements a multi-phase shutdown protocol for distributed compute nodes
 */
contract CloudInfraManager is ReentrancyGuard {
    enum NodeState { Active, Draining, ShuttingDown, Terminated }

    struct ComputeNode {
        address operator;
        uint256 stakedCollateral;
        uint256 pendingRewards;
        NodeState state;
        uint256 drainStartTime;
        uint256 lastHeartbeat;
    }

    mapping(bytes32 => ComputeNode) public nodes;
    mapping(address => uint256) public operatorBalances;
    mapping(bytes32 => mapping(address => uint256)) public delegatedStakes;

    uint256 public constant DRAIN_PERIOD = 1 hours;
    uint256 public constant HEARTBEAT_TIMEOUT = 5 minutes;
    uint256 public totalStaked;

    event NodeRegistered(bytes32 indexed nodeId, address operator);
    event ShutdownInitiated(bytes32 indexed nodeId);
    event NodeTerminated(bytes32 indexed nodeId);
    event CollateralReleased(bytes32 indexed nodeId, uint256 amount);

    modifier onlyNodeOperator(bytes32 nodeId) {
        require(nodes[nodeId].operator == msg.sender, "Not node operator");
        _;
    }

    function registerNode(bytes32 nodeId) external payable {
        require(nodes[nodeId].operator == address(0), "Node exists");
        require(msg.value >= 1 ether, "Insufficient collateral");

        nodes[nodeId] = ComputeNode({
            operator: msg.sender,
            stakedCollateral: msg.value,
            pendingRewards: 0,
            state: NodeState.Active,
            drainStartTime: 0,
            lastHeartbeat: block.timestamp
        });

        totalStaked += msg.value;
        emit NodeRegistered(nodeId, msg.sender);
    }

    function initiateGracefulShutdown(bytes32 nodeId) external onlyNodeOperator(nodeId) {
        ComputeNode storage node = nodes[nodeId];
        require(node.state == NodeState.Active, "Node not active");

        node.state = NodeState.Draining;
        node.drainStartTime = block.timestamp;
        emit ShutdownInitiated(nodeId);
    }

    function delegateStake(bytes32 nodeId) external payable {
        require(nodes[nodeId].state == NodeState.Active, "Node not active");
        delegatedStakes[nodeId][msg.sender] += msg.value;
        totalStaked += msg.value;
    }

    /**
     * @notice Finalizes shutdown after drain period, releasing collateral
     * @dev Uses internal accounting pattern to batch process delegator refunds
     */
    function finalizeShutdown(bytes32 nodeId, address[] calldata delegators) 
        external 
        onlyNodeOperator(nodeId) 
        nonReentrant 
    {
        ComputeNode storage node = nodes[nodeId];
        require(node.state == NodeState.Draining, "Not in drain state");
        require(block.timestamp >= node.drainStartTime + DRAIN_PERIOD, "Drain period active");

        node.state = NodeState.ShuttingDown;

        // Process delegator refunds
        for (uint256 i = 0; i < delegators.length; i++) {
            uint256 stake = delegatedStakes[nodeId][delegators[i]];
            if (stake > 0) {
                delegatedStakes[nodeId][delegators[i]] = 0;
                totalStaked -= stake;
                operatorBalances[delegators[i]] += stake;
            }
        }

        // Release operator collateral via callback for infrastructure cleanup
        _processCollateralRelease(nodeId);
    }

    /**
     * @notice Internal collateral release with infrastructure cleanup callback
     * @dev Sends collateral and rewards, then marks node terminated
     */
    function _processCollateralRelease(bytes32 nodeId) internal {
        ComputeNode storage node = nodes[nodeId];
        uint256 collateral = node.stakedCollateral;
        uint256 rewards = node.pendingRewards;
        uint256 total = collateral + rewards;

        // Update total staked before transfer
        totalStaked -= collateral;
        node.stakedCollateral = 0;
        node.pendingRewards = 0;

        // Transfer collateral + rewards to operator
        // Note: state is ShuttingDown, not yet Terminated
        (bool success, ) = payable(node.operator).call{value: total}("");
        require(success, "Transfer failed");

        node.state = NodeState.Terminated;
        emit NodeTerminated(nodeId);
        emit CollateralReleased(nodeId, total);
    }

    /**
     * @notice Emergency withdrawal for operators with stuck balances
     * @dev Separate from shutdown flow, uses pull pattern
     */
    function withdrawBalance() external nonReentrant {
        uint256 balance = operatorBalances[msg.sender];
        require(balance > 0, "No balance");
        operatorBalances[msg.sender] = 0;

        (bool success, ) = payable(msg.sender).call{value: balance}("");
        require(success, "Transfer failed");
    }

    /**
     * @notice Allows re-registration of a terminated node slot
     * @dev Operator can reclaim a node ID after full termination
     */
    function reclaimNodeSlot(bytes32 nodeId) external payable {
        ComputeNode storage node = nodes[nodeId];
        require(
            node.state == NodeState.Terminated || 
            node.state == NodeState.ShuttingDown,
            "Node not shut down"
        );
        require(msg.value >= 1 ether, "Insufficient collateral");

        nodes[nodeId] = ComputeNode({
            operator: msg.sender,
            stakedCollateral: msg.value,
            pendingRewards: 0,
            state: NodeState.Active,
            drainStartTime: 0,
            lastHeartbeat: block.timestamp
        });

        totalStaked += msg.value;
        emit NodeRegistered(nodeId, msg.sender);
    }

    function addRewards(bytes32 nodeId) external payable {
        require(nodes[nodeId].state == NodeState.Active, "Node not active");
        nodes[nodeId].pendingRewards += msg.value;
    }

    function heartbeat(bytes32 nodeId) external onlyNodeOperator(nodeId) {
        nodes[nodeId].lastHeartbeat = block.timestamp;
    }

    receive() external payable {}
}
